#0008}.portrait span{font:600 23px Cinzel;color:#f0e2c7}.portrait i{position:absolute;width:6px;height:6px;background:#c58364;border-radius:50%;right:2px;bottom:2px;box-shadow:0 0 7px #e58b71}.bars{flex:1}.bar-label{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:.15em;color:#d4cabe;margin:0 0 5px}.bar-label b{font-size:9px;letter-spacing:.08em;font-weight:500;color:#e8ddd0}.bar{height:5px;width:100%;background:#272526;border:1px solid #ffffff12;overflow:hidden}.bar i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#8b292d,#d05a4a);box-shadow:0 0 9px #dc524c77;transition:width .18s}.bar-label.second{margin-top:9px;color:#aaa396}.bar.stamina{height:3px}.bar.stamina i{background:linear-gradient(90deg,#737d6b,#c7b779);box-shadow:0 0 7px #c5b87966}.souls{margin-top:9px;display:flex;align-items:center;gap:6px;font-size:11px;color:#e1c38a}.souls small{font-size:8px;letter-spacing:.14em;color:#aaa}.soul-gem{font-size:10px;text-shadow:0 0 8px #f4cb70}.boss-hud{position:absolute;z-index:3;bottom:74px;left:50%;transform:translateX(-50%);width:min(430px,54vw);opacity:0;transition:opacity .5s;pointer-events:none}.boss-hud.visible{opacity:1}.boss-title{text-align:center;margin-bottom:8px;font:500 11px Cinzel;letter-spacing:.2em;color:#e7d8c3;text-shadow:0 2px 6px #000}.boss-title small{display:block;font:10px 'DM Sans';letter-spacing:.1em;color:#b1a69a;margin-top:4px}.boss-track{height:8px;border:1px solid #927e697a;background:#201c1b;box-shadow:0 3px 12px #0009}.boss-track i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#751e25,#c64d43);transition:width .25s}.objective{position:absolute;z-index:3;right:4vw;top:106px;display:flex;align-items:center;gap:10px;padding:10px 13px;background:linear-gradient(90deg,#191918aa,#18171655);border-right:1px solid #bd9d6966;max-width:290px}.objective-icon{font:22px Cinzel;color:#dfbd82}.objective small{font-size:8px;letter-spacing:.2em;color:#bcaa8f;displ