px;border-radius:50%;border:1px solid #e8ddc333;background:#13141782;box-shadow:inset 0 0 25px #0008;display:grid;place-items:center;backdrop-filter:blur(3px)}.stick-knob{width:46px;height:46px;border-radius:50%;border:1px solid #e2d5be88;background:radial-gradient(circle at 35% 30%,#82776b,#403e3d);box-shadow:0 3px 12px #0009;transform:translate(0,0)}.action-buttons{display:flex;align-items:flex-end;gap:9px;pointer-events:auto}.action{border:1px solid #e1d2b955;color:#f0e7d7;border-radius:50%;background:radial-gradient(circle at 40% 30%,#49433cdd,#171719ee);width:62px;height:62px;display:flex;flex-direction:column;justify-content:center;align-items:center;box-shadow:0 4px 18px #0009;touch-action:none;user-select:none;-webkit-user-select:none}.action span{font-size:21px;line-height:24px}.action small{font:7px 'DM Sans';letter-spacing:.12em;color:#d2c4ac}.action.attack{width:74px;height:74px;border-color:#c49b6877;background:radial-gradient(circle at 40% 30%,#67423c,#251c1c)}.action.dodge{margin-bottom:4px}.action.interact{width:50px;height:50px;margin-bottom:2px}.action.interact span{font-size:16px}.action:active{transform:scale(.94);filter:brightness(1.3)}.loading{position:absolute;inset:0;z-index:10;background:#111214;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loader-mark{font-size:38px;color:#d8b777;animation:pulse 1.5s infinite}.loading span{font:10px Cinzel;letter-spacing:.25em;color:#b9ab94}@keyframes pulse{50%{opacity:.35;transform:scale(.85)}}
